import{_ as t,c as e,o as a,a6 as l}from"./chunks/framework.CZHnDj0c.js";const u=JSON.parse('{"title":"相机核心三要素：帧率、曝光与增益","description":"","frontmatter":{},"headers":[],"relativePath":"src/camera/basicData.md","filePath":"src/camera/basicData.md"}'),r={name:"src/camera/basicData.md"},n=l('<h1 id="相机核心三要素-帧率、曝光与增益" tabindex="-1">相机核心三要素：帧率、曝光与增益 <a class="header-anchor" href="#相机核心三要素-帧率、曝光与增益" aria-label="Permalink to &quot;相机核心三要素：帧率、曝光与增益&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>帧率（Frame Rate）、曝光（Exposure）和增益（Gain/ISO）是视频与摄影中最基础、最核心的三个概念。理解它们各自的定义以及三者之间的制约关系，是掌握相机使用的第一步。</p><hr><h2 id="_1-曝光-exposure" tabindex="-1">1. 曝光 (Exposure) <a class="header-anchor" href="#_1-曝光-exposure" aria-label="Permalink to &quot;1. 曝光 (Exposure)&quot;">​</a></h2><h3 id="_1-1-核心概念" tabindex="-1">1.1 核心概念 <a class="header-anchor" href="#_1-1-核心概念" aria-label="Permalink to &quot;1.1 核心概念&quot;">​</a></h3><p>曝光决定了画面的整体明暗程度。目标是获得“曝光正确”的图像，避免“过曝”（太亮，丢失亮部细节）或“欠曝”（太暗，丢失暗部细节）。</p><h3 id="_1-2-曝光三角" tabindex="-1">1.2 曝光三角 <a class="header-anchor" href="#_1-2-曝光三角" aria-label="Permalink to &quot;1.2 曝光三角&quot;">​</a></h3><p>曝光由三个参数共同控制，它们像一个三角形的三条边，相互影响、相互制约。</p><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">类比</th><th style="text-align:left;">作用</th><th style="text-align:left;">提高带来的影响</th><th style="text-align:left;">主要副作用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>光圈 (Aperture)</strong></td><td style="text-align:left;"><strong>水龙头阀门的大小</strong></td><td style="text-align:left;">控制单位时间内的进光量</td><td style="text-align:left;">画面变亮</td><td style="text-align:left;"><strong>景深变浅</strong>（背景虚化效果更强）</td></tr><tr><td style="text-align:left;"><strong>快门速度 (Shutter Speed)</strong></td><td style="text-align:left;"><strong>阀门打开的时间</strong></td><td style="text-align:left;">控制感光元件感光的时间</td><td style="text-align:left;">画面变亮</td><td style="text-align:left;"><strong>运动模糊增加</strong>（速度越慢，拖影越明显）</td></tr><tr><td style="text-align:left;"><strong>感光度 (ISO / Gain)</strong></td><td style="text-align:left;"><strong>工人的工作效率</strong></td><td style="text-align:left;">放大传感器接收到的信号强度</td><td style="text-align:left;">画面变亮</td><td style="text-align:left;"><strong>噪点增加</strong>（画质下降）</td></tr></tbody></table><h3 id="_1-3-如何平衡曝光三角" tabindex="-1">1.3 如何平衡曝光三角 <a class="header-anchor" href="#_1-3-如何平衡曝光三角" aria-label="Permalink to &quot;1.3 如何平衡曝光三角&quot;">​</a></h3><p>调整曝光的过程，就是在<strong>画质</strong>（低ISO）、<strong>景深</strong>（光圈）和<strong>动态模糊</strong>（快门）之间根据自己的创作需求进行取舍和平衡。</p><hr><h2 id="_2-帧率-frame-rate-fps" tabindex="-1">2. 帧率 (Frame Rate, FPS) <a class="header-anchor" href="#_2-帧率-frame-rate-fps" aria-label="Permalink to &quot;2. 帧率 (Frame Rate, FPS)&quot;">​</a></h2><h3 id="_2-1-核心概念" tabindex="-1">2.1 核心概念 <a class="header-anchor" href="#_2-1-核心概念" aria-label="Permalink to &quot;2.1 核心概念&quot;">​</a></h3><p>帧率是指视频<strong>每秒记录的静态画面（帧）的数量</strong>，单位为 FPS (Frames Per Second)。帧率决定了视频画面的流畅度以及能否用于慢动作播放。</p><h3 id="_2-2-常见帧率及其应用" tabindex="-1">2.2 常见帧率及其应用 <a class="header-anchor" href="#_2-2-常见帧率及其应用" aria-label="Permalink to &quot;2.2 常见帧率及其应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">帧率 (FPS)</th><th style="text-align:left;">主要应用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>24 / 25</strong></td><td style="text-align:left;">电影标准帧率，营造独特的“电影感”</td></tr><tr><td style="text-align:left;"><strong>30</strong></td><td style="text-align:left;">电视、网络视频常用帧率，比24/25帧更流畅</td></tr><tr><td style="text-align:left;"><strong>60 / 120 / 240+</strong></td><td style="text-align:left;"><strong>高速帧率</strong>，常用于拍摄运动场景、游戏视频，或用于制作<strong>平滑的慢动作</strong>效果</td></tr></tbody></table><blockquote><p><strong>慢动作原理</strong>：用高帧率（如60FPS）拍摄，以低帧率（如30FPS）播放，播放时间延长，从而实现慢放。60FPS → 30FPS播放 = 2倍慢放。</p></blockquote><h3 id="_2-3-帧率与快门速度的关系-180°快门法则" tabindex="-1">2.3 帧率与快门速度的关系（180°快门法则） <a class="header-anchor" href="#_2-3-帧率与快门速度的关系-180°快门法则" aria-label="Permalink to &quot;2.3 帧率与快门速度的关系（180°快门法则）&quot;">​</a></h3><p>为了获得最自然流畅的动态模糊效果，视频拍摄中通常遵循一条经验法则： <strong>快门速度 ≈ 1 / (2 × 帧率)</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">帧率 (FPS)</th><th style="text-align:left;">推荐快门速度</th></tr></thead><tbody><tr><td style="text-align:left;">24</td><td style="text-align:left;">1/50s</td></tr><tr><td style="text-align:left;">30</td><td style="text-align:left;">1/60s</td></tr><tr><td style="text-align:left;">60</td><td style="text-align:left;">1/120s</td></tr></tbody></table><p><strong>重要影响</strong>：提高帧率（如从30FPS升至60FPS）意味着必须提高快门速度（从1/60s升至1/120s）。<strong>快门速度提高，进光量减少，画面会变暗</strong>。此时必须通过开大光圈或提高ISO来补偿曝光。</p><hr><h2 id="_3-增益-gain-iso" tabindex="-1">3. 增益 (Gain) / ISO <a class="header-anchor" href="#_3-增益-gain-iso" aria-label="Permalink to &quot;3. 增益 (Gain) / ISO&quot;">​</a></h2><h3 id="_3-1-核心概念" tabindex="-1">3.1 核心概念 <a class="header-anchor" href="#_3-1-核心概念" aria-label="Permalink to &quot;3.1 核心概念&quot;">​</a></h3><p>增益（在专业摄像机中常用）和ISO（在消费级相机中常用）在数码领域<strong>本质是相同的</strong>。它指的是相机内部对图像传感器输出信号的<strong>放大程度</strong>。</p><h3 id="_3-2-工作原理与副作用" tabindex="-1">3.2 工作原理与副作用 <a class="header-anchor" href="#_3-2-工作原理与副作用" aria-label="Permalink to &quot;3.2 工作原理与副作用&quot;">​</a></h3><ul><li><strong>工作原理</strong>：它并非提升传感器本身的感光能力，而是将捕获到的原始信号（包括有用的图像信号和固有的噪点信号）进行<strong>电子放大</strong>。</li><li><strong>核心副作用</strong>：<strong>画质下降和噪点增加</strong>。增益/ISO越高，画面中的彩色或黑白噪点（颗粒感）就越明显，细节和色彩纯净度下降。</li><li><strong>使用策略</strong>：<strong>作为最后的手段</strong>。优先使用光圈和快门控制曝光，只有在它们都无法满足需求时（如光圈已最大，快门已最慢），才提高增益/ISO。</li></ul><hr><h2 id="_4-三者的联动与设置策略" tabindex="-1">4. 三者的联动与设置策略 <a class="header-anchor" href="#_4-三者的联动与设置策略" aria-label="Permalink to &quot;4. 三者的联动与设置策略&quot;">​</a></h2><h3 id="_4-1-相互关系总结" tabindex="-1">4.1 相互关系总结 <a class="header-anchor" href="#_4-1-相互关系总结" aria-label="Permalink to &quot;4.1 相互关系总结&quot;">​</a></h3><ul><li><strong>帧率</strong> 决定了 <strong>快门速度</strong> 的基准值。</li><li><strong>快门速度</strong> 和 <strong>光圈</strong> 是控制曝光的主力，直接影响画质（模糊、景深）。</li><li><strong>增益/ISO</strong> 是补偿曝光的备用方案，会牺牲画质。</li></ul><h3 id="_4-2-视频拍摄设置流程-推荐步骤" tabindex="-1">4.2 视频拍摄设置流程（推荐步骤） <a class="header-anchor" href="#_4-2-视频拍摄设置流程-推荐步骤" aria-label="Permalink to &quot;4.2 视频拍摄设置流程（推荐步骤）&quot;">​</a></h3><ol><li><strong>定帧率</strong>：根据创作意图（正常视频 or 慢动作）确定帧率（如 25FPS or 60FPS）。</li><li><strong>定快门</strong>：根据180°法则，设定快门速度（如 25FPS → 1/50s；60FPS → 1/120s）。</li><li><strong>定光圈</strong>：根据想要的景深（虚化程度）设定光圈值（想要虚化用大光圈，如f/2.8；想要全景清晰用小光圈，如f/8）。</li><li><strong>调曝光</strong>：观察画面亮度。 <ul><li><strong>如果画面太暗</strong>： <ul><li>优先考虑开大光圈。</li><li>如果光圈已到最大，可适当提高增益/ISO。</li></ul></li><li><strong>如果画面太亮</strong>： <ul><li>优先考虑缩小光圈。</li><li>如果想保持大光圈虚化效果，必须使用 <strong>ND减光镜</strong>（中性密度镜）来物理减光。</li></ul></li></ul></li></ol><hr><h2 id="_5-焦距" tabindex="-1">5.焦距 <a class="header-anchor" href="#_5-焦距" aria-label="Permalink to &quot;5.焦距&quot;">​</a></h2><h3 id="_5-1焦距的定义" tabindex="-1">5.1焦距的定义 <a class="header-anchor" href="#_5-1焦距的定义" aria-label="Permalink to &quot;5.1焦距的定义&quot;">​</a></h3><ul><li>焦距是镜头的光学中心到相机传感器的距离。</li><li>焦距越短，景深越浅，画面越清晰,<strong>视角越大,拍摄的场景越大</strong>。</li><li>焦距越长，景深越深，画面越模糊,<strong>视角越窄,拍摄的场景越小,物体在图像显的更大</strong>。</li></ul><h3 id="_5-2变焦镜头和定焦镜头" tabindex="-1">5.2变焦镜头和定焦镜头 <a class="header-anchor" href="#_5-2变焦镜头和定焦镜头" aria-label="Permalink to &quot;5.2变焦镜头和定焦镜头&quot;">​</a></h3><ul><li>定焦镜头：焦距固定，不随光圈变化。</li><li>变焦镜头：焦距可变，随光圈变化，手动切换到手动对焦(MF/M)。</li><li>一般都是以<strong>mm</strong>为单位。如23mm镜头，53mm镜头。35-50mm是变焦镜头。</li><li>拍摄运动物体一般使用自动对焦(AF)</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">它主要控制什么？</th><th style="text-align:left;">调整它的主要代价是什么？</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>帧率 (FPS)</strong></td><td style="text-align:left;">流畅度与慢放能力</td><td style="text-align:left;">决定了快门速度，从而影响进光量</td></tr><tr><td style="text-align:left;"><strong>光圈 (Aperture)</strong></td><td style="text-align:left;">景深（背景虚化程度）</td><td style="text-align:left;">虚化效果或画面清晰范围</td></tr><tr><td style="text-align:left;"><strong>快门速度 (Shutter)</strong></td><td style="text-align:left;">动态模糊（运动轨迹）</td><td style="text-align:left;">运动物体的拖影或凝固程度</td></tr><tr><td style="text-align:left;"><strong>增益/ISO (Gain/ISO)</strong></td><td style="text-align:left;">信号灵敏度（画面亮度）</td><td style="text-align:left;"><strong>画质噪点</strong></td></tr></tbody></table>',43),s=[n];function o(i,d,g,h,f,x){return a(),e("div",null,s)}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
